```java
public interface PaymentHandler { boolean supports(String type); void process(Payment p); }

@Component public class StripeHandler implements PaymentHandler { ... }
@Component public class PayPalHandler implements PaymentHandler { ... }

@Service
public class PaymentService {
    @Autowired
    private List<PaymentHandler> handlers; // ALL implementations injected

    public void process(Payment payment) {
        handlers.stream()
            .filter(h -> h.supports(payment.getType()))
            .findFirst()
            .ifPresent(h -> h.process(payment));
    }
}
